import hashlib,html,json,pathlib,statistics
base=pathlib.Path('/root/.local/state/rust-full-migration-20261028-lu443ytp/artifacts/expressive-tts')
out=pathlib.Path('/root/saas-rust/migration-notes/evidence/2026-10-29-expressive-tts');out.mkdir(parents=True,exist_ok=True)
raw=(base/'expressive-benchmark-inputs.json').read_bytes();identity=hashlib.sha256(raw).hexdigest();inputs=json.loads(raw)
node=json.loads((base/'expressive-node-benchmark.json').read_text());rust=json.loads((base/'expressive-rust-benchmark.json').read_text())
assert node['inputSha256']==rust['inputSha256']==identity
assert len(inputs['workloads'])==len(node['runs'])==len(rust['runs'])==9
rows=[]
for w,n,r in zip(inputs['workloads'],node['runs'],rust['runs']):
 assert w['name']==n['name']==r['name'];assert w['iterations']==n['iterations']==r['iterations'];assert n['expectedUnitsChecksum']==r['expectedUnitsChecksum']==w['expectedUnitsChecksum'];assert n['resultChecksum']==r['resultChecksum']==(w['expectedUnitsChecksum']*w['iterations'])&0xffffffff
 assert len(n['samples'])==len(r['samples'])==7
 for run in [n,r]:
  for sample in run['samples']:assert sample['checksum']==n['resultChecksum']
  assert abs(statistics.median(s['elapsedNs']/w['iterations'] for s in run['samples'])-run['medianNsPerOp'])<1e-6
 rows.append({'name':w['name'],'operation':w['op'],'inputUnits':len(w['inputUnits']),'outputUnits':len(w['expectedUnits']),'iterations':w['iterations'],'nodeUs':n['medianUsPerOp'],'rustUs':r['medianUsPerOp'],'rustOverNode':r['medianUsPerOp']/n['medianUsPerOp'],'checksum':n['resultChecksum']})
d={'schema':1,'inputSha256':identity,'scope':'prepared filter/reinforce plus wrapping checksum of every UTF-16 output unit; no preparation or JSON serialization','samples':7,'warmups':100,'sequentialSharedHost':True,'lowerIsBetter':True,'rows':rows}
initial=json.loads((out/'initial-benchmark/comparison.json').read_text());assert initial['inputSha256']==identity
d['initialRows']=initial['rows']
(out/'comparison.json').write_text(json.dumps(d,indent=2)+'\n')
cards=[]
for stage,row in [(stage,row) for stage,data in [('final',rows),('baseline',initial['rows'])] for row in data]:
 maximum=max(row['nodeUs'],row['rustUs']);ratio=row['rustOverNode'];status='lower' if ratio<1 else 'higher'
 label=html.escape(row['name'].replace('filter-','Filter · ').replace('reinforce-','Reinforce · ').replace('-',' '))
 cards.append(f'''<article class="pair" data-op="{row['operation']}" data-stage="{stage}" {"hidden" if stage=="baseline" else ""}><div class="line"><strong>{label}</strong><span class="ratio {'regression' if ratio>1 else ''}">{ratio:.3f}× Rust/Node</span></div><div class="meta">{row['inputUnits']:,} input UTF-16 units · {row['iterations']:,} operations per sample</div><div class="measure"><span>TypeScript</span><b>{row['nodeUs']:.3f} µs</b></div><div class="track"><i class="node" style="width:{row['nodeUs']/maximum*100:.5f}%"></i></div><div class="measure"><span>Rust</span><b>{row['rustUs']:.3f} µs</b></div><div class="track"><i class="rust {'slow' if ratio>1 else ''}" style="width:{row['rustUs']/maximum*100:.5f}%"></i></div></article>''')
page='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Expressive TTS prepared-operation benchmark</title><style>
*{box-sizing:border-box}body{margin:0;color:var(--foreground);font-family:var(--font-sans,system-ui)}p{line-height:1.5;margin:0 0 12px} .muted,.meta{color:var(--muted-foreground);font-size:12px}.controls{display:flex;gap:8px;margin:16px 0;flex-wrap:wrap}button{font:inherit;color:var(--foreground);background:var(--secondary);border:1px solid var(--border);border-radius:var(--radius,8px);padding:7px 12px;cursor:pointer}button[aria-pressed=true]{border-color:var(--primary);box-shadow:0 0 0 1px var(--primary)}.grid{display:grid;gap:10px}.pair{padding:16px;border-radius:var(--radius,10px);background:var(--card)}.line{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:baseline;gap:8px;font-size:14px}.ratio{font-family:var(--font-mono,monospace);font-size:12px;color:var(--success)}.ratio.regression{color:var(--destructive)}.meta{margin:5px 0 11px}.measure{display:flex;justify-content:space-between;font-size:12px;line-height:1.8}.track{height:7px;background:var(--secondary);border-radius:8px;overflow:hidden;margin-bottom:5px}.track i{height:7px;display:block;border-radius:8px}.node{background:var(--chart-1)}.rust{background:var(--chart-2)}.rust.slow{background:var(--destructive)}footer{margin-top:14px;font-size:12px;line-height:1.5;color:var(--muted-foreground)}code{font-family:var(--font-mono,monospace);overflow-wrap:anywhere;font-size:10px}@media(min-width:650px){.grid{grid-template-columns:1fr 1fr}}
</style></head><body><p>Median time per prepared operation, including a checksum over every UTF-16 output unit. <strong>Lower is better.</strong></p><p class="muted">7 samples · 100 warmups · each pair has its own bar scale · exact outputs and sample checksums match</p><div class="controls" role="group" aria-label="Candidate"><button aria-pressed="true" data-stage="final">Optimized</button><button aria-pressed="false" data-stage="baseline">Initial baseline</button></div><div class="controls" role="group" aria-label="Operation filter"><button aria-pressed="true" data-kind="all">All operations</button><button aria-pressed="false" data-kind="filter">Filter</button><button aria-pressed="false" data-kind="reinforce">Reinforce</button></div><main class="grid">'''+''.join(cards)+'''</main><footer>Node 24.22.1 / V8 13.6.233.17-node.58; Rust 1.99.1 release. Sequential runs on one shared host in capped disposable containers. Timings exclude input preparation, JSON, file and network I/O. They do not establish provider latency, whole-pipeline throughput, CPU/RSS changes or statistical significance. Malformed UTF-16 is preserved by both implementations.<br>Prepared input SHA-256: <code>'''+identity+'''</code></footer><script>let stage='final',kind='all';const update=()=>document.querySelectorAll('.pair').forEach(card=>card.hidden=card.dataset.stage!==stage||(kind!=='all'&&card.dataset.op!==kind));for(const field of ['stage','kind'])document.querySelectorAll('button[data-'+field+']').forEach(button=>button.addEventListener('click',()=>{if(field==='stage')stage=button.dataset.stage;else kind=button.dataset.kind;document.querySelectorAll('button[data-'+field+']').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));update()}));</script></body></html>'''
(out/'comparison.html').write_text(page+'\n')
print(json.dumps(d,indent=2))
